// Synth Horde (ex-Neon Bonk) — textes du jeu dans les six langues du site.
// Écrit en groupes ({ w: { blaster: … } } → 'nb.w.blaster') puis aplati par pack().
// Une valeur est un texte avec des {variables} ou une fonction v => … (pluriels).
const s = (n, one, many) => (n === 1 ? one : many);
function pack(o) {
  const out = {};
  for (const [k, v] of Object.entries(o)) {
    if (v && typeof v === 'object') for (const [k2, v2] of Object.entries(v)) out[`nb.${k}.${k2}`] = v2;
    else out['nb.' + k] = v;
  }
  return out;
}

